package org.apache.commons.cli;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for OptionBuilder.withArgName(String)
 */
public class OptionBuilderWithArgNameTest {

    private Field argNameField;
    private Field instanceField;

    @BeforeEach
    public void setUp() throws Exception {
        Class<OptionBuilder> clazz = OptionBuilder.class;
        argNameField = clazz.getDeclaredField("argName");
        argNameField.setAccessible(true);

        instanceField = clazz.getDeclaredField("INSTANCE");
        instanceField.setAccessible(true);

        // Ensure a clean state before each test
        argNameField.set(null, null);
    }

    @AfterEach
    public void tearDown() throws Exception {
        // Reset static argName after each test to avoid cross-test interference
        if (argNameField != null) {
            argNameField.set(null, null);
        }
    }

    @Test
    public void testWithArgNameSetsArgNameAndReturnsSameInstance() throws Exception {
        // Set an initial value to ensure it gets overwritten
        argNameField.set(null, "initial");

        OptionBuilder returned = OptionBuilder.withArgName("foo");

        // Verify returned instance is the same as the private INSTANCE
        Object instance = instanceField.get(null);
        assertSame(instance, returned, "withArgName should return the singleton INSTANCE");

        // Verify the private static argName was set to "foo"
        Object currentArgName = argNameField.get(null);
        assertEquals("foo", currentArgName, "argName should be updated to the provided value");

        // Call again with another value to ensure it overwrites existing value
        OptionBuilder.withArgName("bar");
        assertEquals("bar", argNameField.get(null), "argName should be overwritten by subsequent calls");
    }

    @Test
    public void testWithArgNameAcceptsNull() throws Exception {
        // Set a non-null initial value
        argNameField.set(null, "non-null");

        OptionBuilder returned = OptionBuilder.withArgName(null);

        // INSTANCE returned
        Object instance = instanceField.get(null);
        assertSame(instance, returned, "withArgName should return the singleton INSTANCE even when given null");

        // argName should now be null
        assertNull(argNameField.get(null), "argName should be set to null when null is passed");
    }

    @Test
    public void testWithArgNameEmptyString() throws Exception {
        // Ensure clean start
        argNameField.set(null, null);

        OptionBuilder returned = OptionBuilder.withArgName("");

        // INSTANCE returned
        Object instance = instanceField.get(null);
        assertSame(instance, returned, "withArgName should return the singleton INSTANCE for empty string");

        // argName should be empty string
        Object currentArgName = argNameField.get(null);
        assertEquals("", currentArgName, "argName should be the empty string when empty string is passed");
    }
}

